//! Theming for the tour overlay.
//!
//! Loads the ecosystem's shared stylesheet (generated by `bread-theme` from
//! the extracted wallpaper palette) and layers only the tour's own rules on
//! top, so the callout picks up the same accent the help window and
//! bos-settings show.

use gtk4::CssProvider;
use std::cell::RefCell;

const APP_CSS: &str = "\
/* The shared stylesheet's `window { background-color: @bg }` rule matches \
   every GtkWindow including these; without this override GTK paints that \
   opaque backdrop before the translucent mask box composites onto it, so the \
   alpha never reaches the compositor and the \"dim\" reads as solid black. A \
   class-qualified selector beats the shared rule's bare type selector on \
   specificity regardless of stylesheet load order. */\n\
window.tour-window { background-color: transparent; }\n\
.tour-mask { background-color: rgba(0, 0, 0, 0.65); }\n\
.tour-callout { \
  background-color: @surface; \
  color: @on-surface; \
  border: 1px solid alpha(@on-surface, 0.10); \
  border-radius: 14px; \
  padding: 18px 20px; \
}\n\
.tour-title { font-family: 'Outfit', 'Varela Round', sans-serif; font-weight: 500; font-size: 20px; }\n\
.tour-heading { font-weight: bold; }\n\
.tour-body { color: alpha(@on-surface, 0.85); }\n\
.tour-dim { color: alpha(@on-surface, 0.62); font-size: 12.5px; }\n\
.tour-panel { \
  background-color: alpha(@on-surface, 0.04); \
  border: 1px solid alpha(@on-surface, 0.08); \
  border-radius: 10px; \
  padding: 10px 12px; \
}\n\
/* The one payoff line in the whole tour: the user did the real thing and \
   the compositor proved it, so it reads as its own accent panel, not the \
   same throwaway meta text as the step counter. */\n\
.tour-confirmed { \
  background-color: alpha(@accent, 0.16); \
  border: 1px solid alpha(@accent, 0.55); \
  border-radius: 10px; \
  padding: 10px 12px; \
}\n\
.tour-check { \
  background-color: @accent; \
  color: @on-accent; \
  border-radius: 999px; \
  min-width: 22px; \
  min-height: 22px; \
  font-weight: bold; \
}\n\
.tour-dot { min-width: 6px; min-height: 6px; border-radius: 999px; background-color: alpha(@on-surface, 0.2); }\n\
.tour-dot.done { background-color: alpha(@accent, 0.55); }\n\
.tour-dot.current { min-width: 18px; background-color: @accent; }\n\
@keyframes tour-pulse { \
  0% { box-shadow: 0 0 0 0 alpha(@accent, 0.55); } \
  70% { box-shadow: 0 0 0 8px alpha(@accent, 0); } \
  100% { box-shadow: 0 0 0 0 alpha(@accent, 0); } \
}\n\
.tour-live { \
  min-width: 8px; \
  min-height: 8px; \
  margin: 0 4px; \
  border-radius: 999px; \
  background-color: @accent; \
  animation: tour-pulse 1.6s infinite; \
}\n\
label.keycap { \
  font-size: 12px; \
  padding: 2px 8px; \
  border-radius: 6px; \
  background-color: alpha(@on-surface, 0.08); \
  border: 1px solid alpha(@on-surface, 0.14); \
  border-bottom-width: 2px; \
}\n\
.tour-callout button { border-radius: 10px; padding: 8px 14px; }\n\
.tour-callout button.flat { color: alpha(@on-surface, 0.62); }\n\
";

thread_local! {
    static APP_PROVIDER: RefCell<Option<CssProvider>> = const { RefCell::new(None) };
}

pub fn load() {
    bread_theme::gtk::apply_shared();
    APP_PROVIDER.with(|cell| bread_theme::gtk::apply_css(APP_CSS, cell));
}

pub fn bind_window(window: &impl gtk4::prelude::IsA<gtk4::Native>) {
    bread_theme::gtk::bind_window_auto_with_app_css(window, |_| APP_CSS.to_string());
}
